properties.query:
let wmi_events = SecurityEvent | where EventID == 4624 and ProcessName has "wmiprvse" | summarize wmi_time=min(TimeGenerated) by TargetUserName, Computer;
let schtask_events = SecurityEvent | where EventID == 4698 and TaskName !startswith "\\Microsoft" | summarize schtask_time=min(TimeGenerated) by SubjectUserName, Computer;
wmi_events | join kind=inner schtask_events on $left.TargetUserName == $right.SubjectUserName | where schtask_time - wmi_time between (0min .. 60min)
